<script>
 import {layout,updateViewport} from './layout.svelte';
 import {onMount} from 'svelte';import {SlidersHorizontal,Crop,RotateCw,Columns2,Upload,FolderOpen,Grid2X2,Plus,ArrowUpRight,Sparkles,Save,Check,X,ChevronDown,PanelRightClose,PanelRightOpen,Download,FlipHorizontal,FlipVertical,RotateCcw} from 'lucide-svelte';
 import {studio,current,asset,assets,scope,initialize,dispose,select,run,save,notify,importImages,dropImages,change,undo,redo,isDirty,thumbnails,clearSelection,liveAssets} from './studio.svelte';import {api,initialEdit} from './api';
 import Canvas from './components/Canvas.svelte';import Inspector from './components/Inspector.svelte';import Coverflow from './components/Coverflow.svelte';import Library from './components/Library.svelte';import ExportPanel from './components/Export.svelte';import SettingsPanel from './components/Settings.svelte';import Generate from './components/Generate.svelte';import Assistant from './components/Assistant.svelte';import Review from './components/Review.svelte';import Confirm from './components/Confirm.svelte';
 let radial=$state(null),radialGroup=$state('root'),dragOver=$state(false),visited=$state([]),heldCompare=false,compareBeforeHold=false;
 onMount(()=>{initialize();studio.inspector=window.innerWidth>900;updateViewport();window.addEventListener('resize',updateViewport);return()=>{window.removeEventListener('resize',updateViewport);dispose();};});
 $effect(()=>{if(studio.view==='projects')for(const p of studio.projects)thumbnails(p);});
 $effect(()=>{if(studio.ready&&['generate','export','assistant'].includes(studio.mode)&&!visited.includes(studio.mode))visited.push(studio.mode);});
 const modes=[['edit','Edit'],['generate','Generate'],['export','Export'],['settings','Settings']];
 function mode(value){if(studio.busy)return;studio.mode=value;studio.settingsReturn='';studio.view='canvas';radial=null;}
 let panelVisible=$derived(studio.inspector&&!layout.focus&&studio.mode==='edit'&&studio.view==='canvas');
 function panelOpen(value){return panelVisible&&studio.tool===value&&studio.inspectorTab==='adjust';}
 function tool(value,toggle=false){
  if(studio.busy)return;
  if(toggle&&panelOpen(value)){studio.inspector=false;return;}
  layout.focus=false;studio.tool=value;studio.mode='edit';studio.view='canvas';studio.inspectorTab='adjust';studio.inspector=true;
 }
 function closeInspector(){studio.inspector=false;document.querySelector(`[data-tool="${studio.tool}"]`)?.focus();}
 function toggleInspector(){if(studio.busy||studio.mode!=='edit'||studio.view!=='canvas')return;if(layout.focus){layout.focus=false;studio.inspector=true;}else studio.inspector=!studio.inspector;}

 async function saveNow(){if(!isDirty()){notify('No new changes to save');return;}await run('Saving version',async()=>{const saved=await save([studio.aid]);notify(saved?'Version saved':'No new changes to save');});}
 function step(direction){const list=assets(),i=list.findIndex(a=>a.id===studio.aid);if(list[i+direction])select(list[i+direction].id);}
 function key(e){const editing=e.target instanceof HTMLInputElement||e.target instanceof HTMLTextAreaElement||e.target instanceof HTMLSelectElement;if(e.key==='Escape'){if(studio.confirm){studio.confirm.cancel();return;}radial=null;studio.modal='';studio.compare=false;return;}if(editing||studio.modal||studio.confirm||studio.busy)return;if((e.ctrlKey||e.metaKey)&&e.key==='s'){e.preventDefault();saveNow();return;}if((e.ctrlKey||e.metaKey)&&e.key==='z'){e.preventDefault();e.shiftKey?redo():undo();return;}if(e.ctrlKey&&['1','2','3','4'].includes(e.key)){e.preventDefault();mode(modes[Number(e.key)-1][0]);return;}if(studio.mode==='edit'&&studio.view==='canvas'){if(e.key==='ArrowLeft')step(-1);if(e.key==='ArrowRight')step(1);}if(e.key==='0'){studio.zoom=1;studio.canvasFit=true;studio.pan={x:0,y:0};}if(e.code==='Backslash'&&!heldCompare){compareBeforeHold=studio.compare;heldCompare=true;studio.compare=true;}if(studio.mode==='edit'&&['q','e'].includes(e.key.toLowerCase())){const tools=['adjust','crop','transform'];const i=tools.indexOf(studio.tool);tool(tools[(i+(e.key.toLowerCase()==='q'?tools.length-1:1))%tools.length]);}}
 async function dropped(e){e.preventDefault();dragOver=false;const files=[];async function read(entry){if(entry.isFile){const f=await new Promise((resolve,reject)=>entry.file(resolve,reject));if(f.type.startsWith('image/'))files.push(f);}else if(entry.isDirectory){const reader=entry.createReader();while(true){const children=await new Promise((resolve,reject)=>reader.readEntries(resolve,reject));if(!children.length)break;for(const child of children)await read(child);}}}const entries=[...e.dataTransfer.items].map(i=>i.webkitGetAsEntry?.()).filter(Boolean);if(entries.length){for(const entry of entries)await read(entry);}else files.push(...[...e.dataTransfer.files].filter(f=>f.type.startsWith('image/')));dropImages(files);}
 function context(e){if(studio.mode!=='edit'||studio.view!=='canvas')return;e.preventDefault();radial={x:Math.max(150,Math.min(innerWidth-150,e.clientX)),y:Math.max(150,Math.min(innerHeight-150,e.clientY))};radialGroup='root';}
 function radialAction(action){if(action==='transform'){radialGroup='transform';return;}if(action==='rotate')change({rotation:(studio.draft.rotation+90)%360});else if(action==='flipH')change({flipH:!studio.draft.flipH});else if(action==='flipV')change({flipV:!studio.draft.flipV});else if(action==='reset')change({...initialEdit});else if(action==='compare')studio.compare=!studio.compare;else if(action==='save')saveNow();else if(action==='export')mode('export');else if(action==='import')importImages(false);else tool(action);radial=null;}
</script>
<svelte:window onkeydown={key} onkeyup={e=>{if(e.code==='Backslash'&&heldCompare){studio.compare=compareBeforeHold;heldCompare=false;}}}/>
<div class="app" ondragover={e=>{e.preventDefault();dragOver=true;}} ondragleave={e=>{if(!e.currentTarget.contains(e.relatedTarget))dragOver=false;}} ondrop={dropped} role="application" aria-label="GVPAK STUDIO">
 <header class="app-header" inert={!!studio.busy}><button class="brand" aria-label="Open projects" onclick={()=>{studio.mode='edit';studio.view='projects';}}><span>GVPAK</span><span class="brand-studio">STUDIO</span></button><button class="project-switch" onclick={()=>{studio.mode='edit';studio.view=studio.view==='projects'?'canvas':'projects';}}><span class="project-square"></span>{current()?.name||'Projects'}<ChevronDown size={12}/></button><nav class="mode-tabs" aria-label="Workspace">{#each modes as [value,label]}<button class:active={studio.mode===value} onclick={()=>mode(value)} disabled={!!studio.busy}>{label}</button>{/each}</nav><div class="header-actions"><button class="ai-button" class:active={studio.mode==='assistant'} disabled={!asset()||!!studio.busy} onclick={()=>mode('assistant')}><Sparkles size={15}/>Process</button><button class="save-button" title="Save version · Ctrl+S" disabled={!asset()||!isDirty()||!!studio.busy} onclick={saveNow}><Save size={15}/><span>Save</span></button></div></header>
 <div class="app-workspace"><nav inert={!!studio.busy} class="toolrail" aria-label="Image tools"><button data-tool="adjust" class:chosen={panelOpen('adjust')} onclick={()=>tool('adjust',true)} aria-controls="editor-inspector" aria-expanded={panelOpen('adjust')} title={panelOpen('adjust')?'Adjust · Collapse panel':'Adjust · Open panel'} aria-label="Adjust"><SlidersHorizontal size={20}/></button><button data-tool="crop" class:chosen={panelOpen('crop')} onclick={()=>tool('crop',true)} aria-controls="editor-inspector" aria-expanded={panelOpen('crop')} title={panelOpen('crop')?'Crop · Collapse panel':'Crop · Open panel'} aria-label="Crop"><Crop size={20}/></button><button data-tool="transform" class:chosen={panelOpen('transform')} onclick={()=>tool('transform',true)} aria-controls="editor-inspector" aria-expanded={panelOpen('transform')} title={panelOpen('transform')?'Transform · Collapse panel':'Transform · Open panel'} aria-label="Transform"><RotateCw size={20}/></button><button class:chosen={studio.compare} onclick={()=>{mode('edit');studio.compare=!studio.compare;}} title="Compare" aria-label="Compare"><Columns2 size={20}/></button><span class="rail-divider"></span><button onclick={()=>importImages(false)} disabled={!!studio.busy} title="Import images" aria-label="Import images"><Upload size={20}/></button><button onclick={()=>importImages(true)} disabled={!!studio.busy} title="Import folder" aria-label="Import folder"><FolderOpen size={20}/></button><button class:chosen={studio.view==='grid'} onclick={()=>{const next=studio.view==='grid'?'canvas':'grid';mode('edit');studio.view=next;}} title="Image grid" aria-label="Image grid"><Grid2X2 size={20}/></button><div class="rail-bottom"><button onclick={toggleInspector} disabled={studio.mode!=='edit'||studio.view!=='canvas'} title={panelVisible?'Hide inspector':'Show inspector'} aria-label="Toggle inspector" aria-controls="editor-inspector" aria-expanded={panelVisible}>{#if panelVisible}<PanelRightClose size={19}/>{:else}<PanelRightOpen size={19}/>{/if}</button></div></nav>
 <main class:editing={studio.mode==='edit'} oncontextmenu={context} role="region" aria-label="Workspace content">
 {#if !studio.ready}<div class="empty"><h2>{studio.error?'Could not connect':'Opening workspace'}</h2>{#if studio.error}<button class="primary" onclick={initialize}>Retry</button>{/if}</div>
 {:else if studio.view!=='canvas'&&studio.mode==='edit'}<Library/>
 {:else if studio.mode==='edit'}<div class="editor-canvas"><Canvas/></div>{#if !layout.focus}<Coverflow/>{/if}
 {:else if studio.mode==='settings'}<SettingsPanel/>{/if}
 {#if visited.includes('export')}<div class="workflow-host" hidden={studio.mode!=='export'||!studio.ready}><ExportPanel/></div>{/if}
 {#if visited.includes('generate')}<div class="workflow-host" hidden={studio.mode!=='generate'||!studio.ready}><Generate/></div>{/if}
 {#if visited.includes('assistant')}<div class="workflow-host" hidden={studio.mode!=='assistant'||!studio.ready}><Assistant/></div>{/if}
 </main>{#if studio.inspector&&!layout.focus&&studio.mode==='edit'&&studio.view==='canvas'}<Inspector onclose={closeInspector}/>{/if}</div>
 <footer class="app-footer"><span><i class:working={!!studio.busy}></i>{studio.busy||'Ready'}{#if studio.progress}<b>{studio.progress.done} / {studio.progress.total}</b>{/if}</span><span>{studio.selected.length?`${studio.selected.length} selected`:asset()?'Current image':'No image'}{#if studio.selected.length}<button class="clear-selection" disabled={!!studio.busy} onclick={clearSelection} aria-label="Clear selection">Clear</button>{/if}</span><span class="footer-right">{isDirty()?studio.draftStatus:''}{#if isDirty()}<button class="clear-selection" title="Return to the saved version" onclick={()=>change({...asset().edit})}>Revert draft</button>{/if}<b>GVPAK STUDIO</b></span></footer>
 {#if studio.busy}<div class="busy-pill" role="status"><span class="spinner"></span>{studio.busy}{#if studio.progress}<span>{studio.progress.done}/{studio.progress.total}</span><button onclick={()=>api('cancel_job').catch(e=>studio.error=e.message)}>Cancel remaining</button>{/if}</div>{/if}
 {#if studio.error}<div class="error-notice" role="alert"><span>{studio.error}</span><button aria-label="Dismiss error" onclick={()=>studio.error=''}><X size={15}/></button></div>{/if}
 {#if studio.toast}<div class="toast" role="status"><Check size={15}/>{studio.toast}{#if studio.toastAction}<button onclick={()=>{const action=studio.toastAction;studio.toastAction=null;action.run();}}>{studio.toastAction.label}</button>{/if}</div>{/if}
 {#if studio.notices.length}<div class="job-notice"><b>{studio.notices[0].recipe.summary}</b><span>{studio.notices[0].state}</span><div><button onclick={()=>{studio.processTab='jobs';mode('assistant');}}>View tasks</button><button aria-label="Dismiss task notice" onclick={async()=>{await api('hybrid_ack',{jobId:studio.notices[0].id});studio.notices=studio.notices.slice(1);}}><X size={14}/></button></div></div>{/if}
 {#if studio.confirm}<Confirm/>{/if}
 {#if studio.modal?.type==='review'}<Review/>{/if}
 {#if dragOver}<div class="drop-overlay"><Upload size={32}/><h2>Drop images to import</h2></div>{/if}
 {#if radial}<div class="radial-shade" role="presentation" onclick={e=>{if(e.target===e.currentTarget)radial=null;}}><div class="radial" style:left={`${radial.x}px`} style:top={`${radial.y}px`} role="menu" aria-label="Tools"><button class="radial-center" aria-label="Close tool menu" onclick={()=>radial=null}><X size={18}/></button>{#each (radialGroup==='root'?[['adjust','Adjust',SlidersHorizontal],['crop','Crop',Crop],['transform','Transform',RotateCw],['compare','Compare',Columns2],['export','Export',Download],['save','Save',Save],['import','Import',Upload]]:[['rotate','Rotate',RotateCw],['flipH','Flip H',FlipHorizontal],['flipV','Flip V',FlipVertical],['reset','Reset',RotateCcw]]) as [action,label,Icon],i}<button role="menuitem" style:transform={`translate(${Math.cos(i/(radialGroup==='root'?7:4)*Math.PI*2-Math.PI/2)*100}px,${Math.sin(i/(radialGroup==='root'?7:4)*Math.PI*2-Math.PI/2)*100}px)`} onclick={()=>radialAction(action)}><Icon size={18}/><span>{label}</span></button>{/each}</div></div>{/if}
</div>

